      "relay.health.ended_send_failed": "\u06cc\u06c1 \u0633\u06cc\u0634\u0646 \u062e\u062a\u0645 \u06c1\u0648 \u06af\u06cc\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0628\u06be\u06cc \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u06be\u0648\u0644\u0627 \u0646\u06c1\u06cc\u06ba \u062c\u0627 \u0633\u06a9\u0627\u06d4 \u062f\u0648\u0628\u0627\u0631\u06c1 \u06a9\u0648\u0634\u0634 \u06a9\u0631\u06cc\u06ba\u060c \u06cc\u0627 \u0627\u0648\u067e\u0631 \u201c\u062e\u062a\u0645 \u06c1\u0648 \u06af\u06cc\u0627\u201d \u062f\u0628\u0627\u0626\u06cc\u06ba \u0627\u0648\u0631 \u201c\u062c\u0627\u0631\u06cc \u0631\u06a9\u06be\u06cc\u06ba\u201d \u0645\u0646\u062a\u062e\u0628 \u06a9\u0631\u06cc\u06ba\u06d4",
