    "vi": {
      "relay.health.dropped_detail": "M\u00e1y t\u00ednh c\u1ee7a b\u1ea1n hi\u1ec7n kh\u00f4ng k\u1ebft n\u1ed1i \u0111\u01b0\u1ee3c v\u1edbi phi\u00ean n\u00e0y v\u00e0 v\u1eabn \u0111ang th\u1eed l\u1ea1i. Cho \u0111\u1ebfn khi k\u1ebft n\u1ed1i \u0111\u01b0\u1ee3c, g\u1eedi tin nh\u1eafn s\u1ebd th\u1ea5t b\u1ea1i ngay v\u00e0 n\u1ed9i dung \u0111\u00e3 g\u00f5 v\u1eabn c\u00f2n trong \u00f4 nh\u1eadp.",
      "relay.health.ended_detail": "L\u1ecbch s\u1eed \u0111\u00e3 \u0111\u01b0\u1ee3c l\u01b0u. G\u1eedi tin nh\u1eafn ho\u1eb7c ch\u1ea1m M\u1edf l\u1ea1i \u0111\u1ec3 kh\u00f4i ph\u1ee5c phi\u00ean trong th\u01b0 m\u1ee5c home c\u1ee7a b\u1ea1n.",
      "relay.health.ended_send_failed": "Phi\u00ean n\u00e0y \u0111\u00e3 k\u1ebft th\u00fac v\u00e0 l\u00fac n\u00e0y ch\u01b0a kh\u00f4i ph\u1ee5c \u0111\u01b0\u1ee3c. H\u00e3y th\u1eed g\u1eedi l\u1ea1i, ho\u1eb7c ch\u1ea1m \u201c\u0110\u00e3 k\u1ebft th\u00fac\u201d \u1edf tr\u00ean c\u00f9ng r\u1ed3i ch\u1ecdn M\u1edf l\u1ea1i.",
      "relay.health.live": "\u0110ang ho\u1ea1t \u0111\u1ed9ng",
      "relay.health.live_detail": "\u0110ang ch\u1ea1y tr\u00ean m\u00e1y t\u00ednh c\u1ee7a b\u1ea1n \u2014 tin nh\u1eafn \u0111\u01b0\u1ee3c chuy\u1ec3n \u0111\u1ebfn ngay",
      "relay.health.quiet_detail": "Phi\u00ean n\u00e0y tr\u00ean m\u00e1y t\u00ednh c\u1ee7a b\u1ea1n \u0111\u00e3 ng\u1eebng ph\u1ea3n h\u1ed3i \u2014 c\u00f3 th\u1ec3 \u0111ang b\u1eadn ho\u1eb7c b\u1ecb treo. C\u00f3 th\u1ec3 tin nh\u1eafn b\u00e1o g\u1eedi th\u1ea5t b\u1ea1i nh\u01b0ng v\u1eabn \u0111\u01b0\u1ee3c chuy\u1ec3n \u0111\u1ebfn khi phi\u00ean b\u1eaft k\u1ecbp. Th\u1eed l\u1ea1i s\u1ebd kh\u00f4ng g\u1eedi tin nh\u1eafn hai l\u1ea7n.",
      "relay.health.reconnecting": "\u0110ang k\u1ebft n\u1ed1i l\u1ea1i",
      "relay.health.reconnecting_detail": "\u0110i\u1ec7n tho\u1ea1i n\u00e0y \u0111\u00e3 m\u1ea5t k\u1ebft n\u1ed1i v\u1edbi m\u00e1y t\u00ednh c\u1ee7a b\u1ea1n v\u00e0 \u0111ang li\u00ean t\u1ee5c th\u1eed l\u1ea1i. Phi\u00ean c\u00f3 th\u1ec3 v\u1eabn \u0111ang ch\u1ea1y \u1edf \u0111\u00f3; g\u1eedi tin nh\u1eafn c\u00f3 th\u1ec3 kh\u00f4ng th\u00e0nh c\u00f4ng cho \u0111\u1ebfn khi k\u1ebft n\u1ed1i tr\u1edf l\u1ea1i.",
    },
